const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright (c) 2015 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.settings-window-main {\n  color: var(--color-text-primary);\n  background-color: var(--sys-color-cdt-base-container);\n  padding: 11px 0 0;\n}\n\n.settings-content {\n  overflow-y: auto;\n  overflow-x: hidden;\n  margin: 8px 8px 8px 0;\n  padding: 0 4px;\n  flex: auto;\n}\n\n.settings-container {\n  width: 100%;\n  column-width: 288px;\n}\n\n.settings-block {\n  display: block;\n  padding-bottom: 9px;\n  width: 288px;\n  break-inside: avoid;\n}\n\n.settings-tab.settings-container {\n  column-width: 308px;\n}\n\n.settings-tab .settings-block {\n  margin-left: 20px;\n}\n\n.settings-line {\n  padding-bottom: 5px;\n  margin-bottom: 5px;\n}\n\n.settings-key-cell {\n  display: inline-block;\n  width: 153px;\n  white-space: nowrap;\n  text-align: right;\n  vertical-align: middle;\n  padding-right: 6px;\n}\n\n.settings-cell {\n  display: inline-block;\n  width: 135px;\n  vertical-align: middle;\n}\n\n.settings-section-title {\n  font-size: 120%;\n  text-align: left;\n}\n\n.settings-combine-keys {\n  margin: 0 0.3em;\n  font-size: 9px;\n}\n\nfieldset {\n  margin: 0;\n  padding: 0;\n  border: none;\n}\n\n.experiments-filter {\n  padding-top: 1px;\n  display: flex;\n  align-items: center;\n}\n\nlabel {\n  padding-right: 8px;\n  padding-bottom: 8px;\n}\n\n.settings-tab p {\n  margin: 12px 0;\n}\n\n.settings-block p p {\n  padding-left: 30px;\n}\n\n.settings-select {\n  align-items: center;\n  display: grid;\n}\n\n.settings-experiments-warning-subsection-warning {\n  color: var(--color-accent-red);\n}\n\n.settings-experiments-warning-subsection-message {\n  color: inherit;\n}\n\n.settings-content input[type=\"checkbox\"] {\n  margin: 1px 7px 1px 2px;\n}\n\n.settings-window-title {\n  font-size: 18px;\n  color: var(--color-text-primary);\n  padding: 0 0 5px 13px;\n}\n\n.settings-container-wrapper {\n  position: absolute;\n  top: 31px;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  overflow: auto;\n  padding-top: 9px;\n  border-top: 1px solid var(--sys-color-divider);\n}\n\n.settings-tab.settings-content {\n  margin: 0;\n  padding: 0;\n}\n\n.settings-tab-container {\n  flex: auto;\n  overflow: hidden;\n}\n\n.settings-tab-container header {\n  padding: 0 0 6px;\n}\n\n#experiments-tab-content .settings-container {\n  column-width: auto;\n}\n\n#experiments-tab-content .settings-block {\n  width: auto;\n  margin-left: 0;\n  margin-right: 10px;\n}\n\n.settings-tab-container header > h1 {\n  font-size: 18px;\n  font-weight: normal;\n  margin: 0;\n  padding-bottom: 3px;\n  white-space: nowrap;\n}\n\n.settings-tab .settings-section-title {\n  margin-left: -20px;\n  color: var(--color-text-secondary);\n}\n\n.settings-tab .settings-block label:hover {\n  color: var(--color-text-secondary);\n}\n\n.settings-tab .settings-block fieldset:disabled label:hover {\n  color: inherit;\n}\n\n.settings-tab select {\n  margin-left: 10px;\n  width: 80%;\n}\n\n.settings-experiment {\n  display: grid;\n  grid-template-columns: auto min-content 1fr;\n}\n\n.settings-experiment .devtools-link {\n  display: flex !important; /* stylelint-disable-line declaration-no-important */\n  align-items: center;\n}\n\n.settings-experiment .devtools-link:has(.link-icon) {\n  outline-offset: 0;\n}\n\n.experiment-label {\n  margin-right: 2px;\n}\n\n.settings-experiment-unstable {\n  color: var(--color-text-secondary);\n}\n\n.settings-experiment .feedback-link {\n  color: var(--color-primary-old);\n  text-decoration-line: underline;\n  margin-left: 4px;\n}\n\n.tabbed-pane-content slot::slotted(.widget) {\n  /* '!important' in order to overwrite the slotted widget's 'overflow-auto' class.\n  This prevents the focus-ring of selectable elements from being cut off. */\n  overflow: visible !important; /* stylelint-disable-line declaration-no-important */\n}\n\n@media (forced-colors: active) {\n  .settings-window-title {\n    color: canvastext;\n  }\n\n  .tabbed-pane-header-tab {\n    background: ButtonFace;\n  }\n\n  .tabbed-pane-header-tab-title {\n    color: canvastext;\n  }\n}\n\n@media (forced-colors: active) and (prefers-color-scheme: dark) {\n  .tabbed-pane-header-tab.selected {\n    background: ButtonFace;\n  }\n\n  .tabbed-pane-header-tab.selected .tabbed-pane-header-tab-title {\n    color: HighlightText;\n  }\n}\n\n/*# sourceURL=settingsScreen.css */\n");export default styles;